delete from RSK_ISUP_INDICATOR_PARA_DTL where PARA_CODE='FSMCPBDTZWSSQYGQ' and  PARA_GRANULARITY in ('04','05') AND PARA_DISPLAY_TYPE='SQL';
INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '04', 'SQL', 'SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM TRD_PRODUCT_DEAL t0	
inner join TRD_PRODUCT_DEAL_ADD t1  on t0.TRADE_ID = t1.TRADE_ID	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t0.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t0.TRADE_DATE =date''${valDate}''
UNION ALL	
SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM WFL_TRD_PRODUCT_DEAL t0	
inner join WFL_TRD_PRODUCT_DEAL_ADD t1  on t0.TRADE_ID = t1.TRADE_ID and t0.TRADE_STATUS != ''03''	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t0.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t0.TRADE_DATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);

INSERT INTO "RSK_ISUP_INDICATOR_PARA_DTL" VALUES ('FSMCPBDTZWSSQYGQ', '05', 'SQL', 'SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM PTL_SEC_VALUTION t1	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t1.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', sysdate, 'jjpei', sysdate);